void mainImage(out vec4 O, vec2 U) {
    vec2 p = vec2(U.x, iResolution.y - U.y) / iResolution.xy * 500.;

    vec2 center = vec2(250.);
    vec2 dir = p - center;
    float r = length(dir);
    float a = atan(dir.y, dir.x);
    a += log(r + 1.0) * 0.25;
    p = center + r * vec2(cos(a), sin(a));

    float f = iTime * 60., m = mod(f, 50.), I = floor((p.x + m) / 50.), h = 0., dist;
    int di, dj, k;
    vec3 L = normalize(vec3(.5, .8, -.6)), ro, rd, hp, q, e = vec3(.1, 0, 0), norm, col = vec3(0);

    for (di = -1; di <= 1; di++) {
        float x = (I + float(di)) * 50. - m;
        float rVal = f * 31. / 30. + x;
        float sz = abs(15. * sin(rVal)) + 2.;
        float sX = sin(rVal * .5), cX = cos(rVal * .5);
        float sY = sin(rVal * .7), cY = cos(rVal * .7);
        float sZ = sin(rVal),      cZ = cos(rVal);
        mat3 M = mat3(cZ, -sZ, 0, sZ, cZ, 0, 0, 0, 1) *
                 mat3(cY, 0, sY, 0, 1, 0, -sY, 0, cY) *
                 mat3(1, 0, 0, 0, cX, -sX, 0, sX, cX);
        float nx = x + f, ni = floor(nx), nf = fract(nx);
        float h0 = fract(sin(ni) * 43758.55);
        float h1 = fract(sin(ni + 1.) * 43758.55);
        float nVal = mix(h0, h1, nf * nf * (3. - 2. * nf));
        float yM = mod(-f * (nVal - .5) * 6., 99.);
        float J = floor((p.y - yM) / 99.);

        for (dj = -1; dj <= 1; dj++) {
            float y = (J + float(dj)) * 99. + yM;
            h = 0.;
            ro = M * vec3(p - vec2(x, y), -100);
            rd = M * vec3(0, 0, 1);

            for (k = 0; k++ < 12 && h <= 200.; ) {
                hp = ro + rd * h;
                q = abs(hp) - vec3(sz);
                dist = length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.);
                if (dist < .1) {
                    vec3 qX1 = abs(hp + e.xyy) - vec3(sz), qX2 = abs(hp - e.xyy) - vec3(sz);
                    vec3 qY1 = abs(hp + e.yxy) - vec3(sz), qY2 = abs(hp - e.yxy) - vec3(sz);
                    vec3 qZ1 = abs(hp + e.yyx) - vec3(sz), qZ2 = abs(hp - e.yyx) - vec3(sz);

                    float dX1 = length(max(qX1, 0.)) + min(max(qX1.x, max(qX1.y, qX1.z)), 0.);
                    float dX2 = length(max(qX2, 0.)) + min(max(qX2.x, max(qX2.y, qX2.z)), 0.);
                    float dY1 = length(max(qY1, 0.)) + min(max(qY1.x, max(qY1.y, qY1.z)), 0.);
                    float dY2 = length(max(qY2, 0.)) + min(max(qY2.x, max(qY2.y, qY2.z)), 0.);
                    float dZ1 = length(max(qZ1, 0.)) + min(max(qZ1.x, max(qZ1.y, qZ1.z)), 0.);
                    float dZ2 = length(max(qZ2, 0.)) + min(max(qZ2.x, max(qZ2.y, qZ2.z)), 0.);

                    norm = normalize(vec3(dX1 - dX2, dY1 - dY2, dZ1 - dZ2));
                    float diff = max(dot(norm, L), .15);

                    vec3 baseCol = .5 + .5 * cos(vec3(I + float(di), J + float(dj), 2.) + vec3(0, 2, 4));
                    col = baseCol * diff;
                    k = 12;
                } else h += dist;
            }
        }
    }

    O = vec4(col, 1.0);
}
